.darma-loader-tw-chart-bars { display: flex; align-items: flex-end; justify-content: space-between; gap: calc(var(--loader-size, 120px) * .06); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .65); padding-bottom: calc(var(--loader-size, 120px) * .05); border-bottom: calc(var(--loader-size, 120px) * .025) solid color-mix(in srgb, var(--loader-color, #6366f1) 40%, transparent); box-sizing: border-box; }
.darma-loader-tw-chart-bars span { flex: 1; height: 100%; border-radius: calc(var(--loader-size, 120px) * .03) calc(var(--loader-size, 120px) * .03) 0 0; background: linear-gradient(to top, var(--loader-color, #6366f1), var(--loader-secondary-color, #22d3ee)); transform-origin: bottom center; animation: darma-loader-tw-chart-bars-twGrowBar calc(var(--loader-speed, 1s) * 1.8) ease-in-out infinite; }
.darma-loader-tw-chart-bars span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-tw-chart-bars span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-tw-chart-bars span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .54); }
@keyframes darma-loader-tw-chart-bars-twGrowBar { 0%, 100% { transform: scaleY(.18); } 50% { transform: scaleY(1); } }

